create function public.member_entitlements(p_project uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare r jsonb; begin if not private.member(p_project) then raise exception 'PERMISSION_DENIED'; end if; select coalesce(jsonb_agg(to_jsonb(x)),'[]') into r from (select f.id,f.purchase_id,f.member_user_id,pr.full_name,p.notes,p.purchase_date,f.amount_minor::text,private.source_outstanding(f.id)::text outstanding_minor,greatest(0,private.source_outstanding(f.id)-coalesce((select sum(greatest(0,ci.claimed_minor-coalesce((select sum(sa.amount_minor) from public.settlement_allocations sa join public.financial_events fe on fe.id=sa.event_id where sa.source_allocation_id=f.id and fe.source_id=ci.reimbursement_claim_id and sa.kind='PAYMENT' and fe.status='POSTED'),0))) from public.reimbursement_claim_items ci join public.reimbursement_claims cl on cl.id=ci.reimbursement_claim_id where ci.purchase_funding_allocation_id=f.id and cl.status not in ('rejected','voided','paid')),0))::text available_minor from public.purchase_funding_allocations f join public.purchases p on p.id=f.purchase_id join public.profiles pr on pr.id=f.member_user_id where f.project_id=p_project and f.source_type='MEMBER' and p.status='posted') x; return r; end $$;
revoke all on function public.member_entitlements(uuid) from public;
grant execute on function public.member_entitlements(uuid) to authenticated;
